def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > 500:
                rich_opp += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units < 1.35:
        scarcity = 2
    elif units < 1.65:
        scarcity = 1

    emergency = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if emergency:
        base = max(DAILY_SALARY * 0.92, highest_prev + 2.0)
    elif scarcity == 2:
        base = max(DAILY_SALARY * 0.72, avg_prev + 3.0)
    elif scarcity == 1:
        base = max(DAILY_SALARY * 0.56, avg_prev * 0.92 + 1.5)
    else:
        base = DAILY_SALARY * 0.34

    if highest_prev >= DAILY_SALARY * 1.2 and not pressured:
        base = min(base, DAILY_SALARY * 0.32)
    elif highest_prev >= DAILY_SALARY * 0.95 and not emergency:
        base = min(base, DAILY_SALARY * 0.42)

    if urgent_opp >= 2 and not emergency:
        base *= 0.92
    if rich_opp >= 2 and scarcity >= 1:
        base *= 1.08

    if day >= 8:
        if pressured:
            base *= 1.15
        else:
            base *= 0.95

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if not emergency:
        reserve_floor = min(budget * 0.45, days_left * DAILY_SALARY * 0.28)

    cap = max(0.0, budget - reserve_floor)
    if emergency:
        cap = budget

    bid = min(base, cap)

    if bid < 0:
        bid = 0.0
    if emergency:
        bid = max(bid, min(budget, DAILY_SALARY * 0.88))
    elif pressured and scarcity >= 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.52))

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid a minimal amount to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Determine base bid based on my HP
    critical_hp_threshold = 2
    low_hp_threshold = 4

    if my_status['hp'] <= critical_hp_threshold:
        base_bid = DAILY_SALARY * 1.1 # Bid very aggressively
    elif my_status['hp'] <= low_hp_threshold:
        base_bid = DAILY_SALARY * 0.9  # Bid aggressively
    else:
        base_bid = DAILY_SALARY * 0.6  # Default moderate bid

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Adjust bid based on competitive pressure from yesterday's bids
    if yesterday_bids:
        max_opp_bid = max(yesterday_bids)

        # Calculate available water units and number of active players
        num_water_units = int(day_context['supply'] // WATER_REQ)
        num_active_players = len(alive_opponents) + 1 # Including myself

        # Check for fierce competition (more players than water units)
        is_fierce_competition = num_active_players > num_water_units

        if is_fierce_competition:
            # In fierce competition, bid higher than the max opponent to win
            base_bid = max(base_bid, max_opp_bid + 5.0)
        else:
            # Less fierce competition
            if my_status['hp'] > low_hp_threshold:
                # If healthy, try to save by bidding slightly less than max opponent, but ensure it's still reasonable
                base_bid = min(base_bid, max_opp_bid - 5.0)
                if base_bid < DAILY_SALARY * 0.4: # Ensure a floor even when saving
                    base_bid = DAILY_SALARY * 0.4
            else:
                # If not healthy, still aim to win, but don't overspend unnecessarily
                base_bid = max(base_bid, max_opp_bid + 1.0)

    # Ensure bid is not negative and does not exceed current budget
    return min(my_status['budget'], max(0.0, base_bid))

