def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent aggressiveness from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        lowest_prev_bid = min(yesterday_bids)
    else:
        highest_prev_bid = 0.0
        lowest_prev_bid = 0.0

    # Supply pressure: with water requirement 7, at supply 15-25 there are 2-3 units available.
    # We bias more when supply is low (harder to secure water).
    if supply <= (MIN_SUPPLY + WATER_REQ * 0.0):
        supply_tier = 0
    elif supply < (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        supply_tier = 1
    else:
        supply_tier = 2

    # Base bid target
    # If opponents previously bid high, we slightly overmatch; otherwise stay moderate.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # They were very aggressive; match/overbid depending on our HP.
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        elif hp <= 4.0:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.65
    else:
        # They were not extremely aggressive; still bid enough to beat typical bids.
        if supply_tier == 0:
            target = max(DAILY_SALARY * 0.55, lowest_prev_bid + 5.0)
        elif supply_tier == 1:
            target = max(DAILY_SALARY * 0.50, (lowest_prev_bid + highest_prev_bid) / 2.0)
        else:
            target = max(DAILY_SALARY * 0.45, lowest_prev_bid + 2.0)

        if hp <= 2.0 or no_water_days >= 2:
            target = max(target, DAILY_SALARY * 0.85)
        elif hp <= 4.0:
            target = max(target, DAILY_SALARY * 0.70)

    # Budget safety: don't exceed what we can afford.
    # Also cap to avoid reckless spending near endgame; keep some reserve.
    reserve = 0.15 * DAILY_SALARY
    max_affordable = max(0.0, budget - reserve)

    bid = min(max_affordable, target)

    # If budget is very low, still attempt to secure water when critical.
    if bid <= 0.0:
        if hp <= 2.0 or no_water_days >= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.5)

    # Ensure non-negative and not NaN
    if bid != bid:
        bid = 0.0
    if bid < 0.0:
        bid = 0.0

    return bid
